import copy
geometry=copy.deepcopy(specs['sketchup_create_geometry']['schema']['properties'])
shape=geometry['options'];shape['properties']['size_mm']=array(number(1,1000000),2,2)
tool('draw_geometry','Draw model-axis geometry. Default grouping=auto draws points, lines, faces and native curves directly in the current edit context without temporary groups; closed solids are grouped. Direct drawing can merge/split existing geometry. Refresh IDs afterward. Choose group for isolation or none to require raw geometry. Native raw circular arcs require uniform edit scaling.',
     dict(kind=choice('rectangle','circle','polyline',*geometry['kind']['enum']),name=text(),grouping=dict(type='string',enum=['auto','none','group'],default='auto'),options=shape),['kind','options'])

