f['schema']['properties']['options']['properties'].update(entity_ids=array(pid,1,25),coordinates=choice('model','first_local'),plane=choice('XY','XZ','YZ'),include_hidden=boolean,include_soft=boolean,hidden_geometry=boolean,doublesided_faces=boolean,ifc_mapped_items=boolean,ifc_types=array(choice(*ifc_types),1,len(ifc_types)),ifc_version=choice('IFC 2x3','IFC 4'),standard_ifc_hierarchy=boolean,tessellated_geometry=boolean)
f['description']+=' export_selection_skp: options.entity_ids1..25 root groups/components, coordinates=model(default) or first_local; copies references into a temporary wrapper, saves current SKP format and aborts/verifies cleanup before publishing. No raw face selection or version override. export_dxf2d: required plane XY/XZ/YZ, optional entity_ids(root groups/components/edges/faces), origin_mm,include_hidden,include_soft; own DXF2000 writer, projected LINEs in mm/on layer0, max5000 lines/20000 visited entities, no Pro needed, no occlusion/section clipping/perspective. import_ifc: .ifc, empty options, native Pro importer. export_ifc: whole model;2019-2025 accepts hidden_geometry,doublesided_faces,ifc_mapped_items,ifc_types(default all supported);2026+ accepts ifc_version(default IFC 2x3),standard_ifc_hierarchy,hidden_geometry,tessellated_geometry(IFC4 only). Unsupported version options rejected; no silent option loss. All file actions excluded from batches.'
s=specs['sketchup_style'];s['schema']['properties']['action']['enum']+=['purge_unused','duplicate','delete','export_settings','import_settings']
s['schema']['properties']['options']['properties'].update(confirm_model_wide=boolean,include_shadows=boolean)
s['description']+=' purge_unused: confirm_model_wide=true, rejects pending style edits and verifies selected/scene styles remain. duplicate: name,new_name,optional select/discard_style_changes; requires native duplicate API(SU2026.2+), copies committed style only. delete: name, requires native remove_style(SU2026+) and unused/unselected/not-last style. Neither duplication nor individual deletion is available on2019. export_settings: path(.json),optional name/include_shadows, writes probe-display/1 editable rendering/shadow settings up to16KiB. import_settings: path only, strict JSON and setting validation, applies editable settings with rollback; does not create/switch/commit a Style, no watermark/image assets or full .style export. Query model_query file_style_support first.'
specs['sketchup_model_query']['schema']['properties']['query']['enum'].append('file_style_support')
specs['sketchup_model_query']['description']+=' file_style_support: empty options, reports native Style APIs available on this installation and IFC option generation; translator availability/fidelity still requires real-file verification.'

specs['sketchup_model_file']['description']+=' save_copy requires the model to have been saved once in SketchUp; model_unsaved is returned before native file I/O otherwise.'

target=ROOT/'shared/ToolkitSchemas.json'
target.write_text(json.dumps(specs,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
source=json.dumps(specs,ensure_ascii=True,separators=(',',':')).replace('"','""')
template=(ROOT/'scripts/ToolkitCatalog.template').read_text(encoding='utf-8')
